package ai.mwm.client.updates
import org.junit.Assert.*
import org.junit.Test
class UpdatePolicyTest {
 @Test fun acceptsRepositoryAndReleasePage(){assertEquals("owner/app",publicRepository("https://github.com/owner/app/releases"));assertEquals("owner/app",publicRepository("owner/app"));assertEquals("owner/app",publicRepository("https://github.com/owner/app.git"))}
 @Test fun rejectsCredentialsHostAndQuery(){for(s in listOf("https://evil.com/owner/app","https://github.com/owner/app?token=x","https://owner:token@github.com/owner/app","owner/app/extra")){assertTrue(s,runCatching {publicRepository(s)}.isFailure)}}
 @Test fun stableNumericComparison(){assertTrue(isNewerRelease("v1.10.0","1.4.0"));assertTrue(isNewerRelease("v2.0.0","1.4.0"));assertFalse(isNewerRelease("v1.4.0","1.4.0"));assertFalse(isNewerRelease("v1.3.11","1.4.0"));assertFalse(isNewerRelease("v1.5.0-beta","1.4.0"));assertFalse(isNewerRelease("v9999999999999.0","1.4.0"))}
 @Test fun downloadBoundToConfiguredPublicRelease(){assertTrue(trustedDownload("https://github.com/owner/app/releases/download/v1.5.0/app.apk","owner/app"));for(url in listOf("http://github.com/owner/app/releases/download/v1.5.0/app.apk","https://github.com/owner/other/releases/download/v1.5.0/app.apk","https://evil.com/owner/app/releases/download/v1.5.0/app.apk","https://github.com/owner/app/blob/main/app.apk"))assertFalse(url,trustedDownload(url,"owner/app"))}
 @Test fun redirectsRequireHttpsKnownHost(){assertTrue(trustedUpdateHost("https://release-assets.githubusercontent.com/download?signature=x"));assertFalse(trustedUpdateHost("http://github.com/path"));assertFalse(trustedUpdateHost("https://github.com.evil.com/path"));assertFalse(trustedUpdateHost("https://github.com:444/path"));assertFalse(trustedUpdateHost("https://user@github.com/path"))}
 @Test fun onlySamePackageHigherCodeAndSameSigner(){assertNull(updatePackageProblem("app",150,setOf("original"),"app",151,setOf("original")));assertNotNull(updatePackageProblem("app",150,setOf("original"),"other",151,setOf("original")));assertNotNull(updatePackageProblem("app",150,setOf("original"),"app",150,setOf("original")));assertNotNull(updatePackageProblem("app",150,setOf("original"),"app",149,setOf("original")));assertNotNull(updatePackageProblem("app",150,setOf("original"),"app",151,setOf("different")));assertNotNull(updatePackageProblem("app",150,emptySet(),"app",151,emptySet()))}
}
